package com.inventario.service;
import com.inventario.domain.*; import com.inventario.dto.Dtos.*; import com.inventario.exception.ApiException; import com.inventario.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.*; import java.time.LocalDateTime; import java.util.*;
@Service public class VentaService { private final VentaRepository ventas; private final ClienteRepository clientes; private final ProductoRepository productos; private final FacturaRepository facturas;
 public VentaService(VentaRepository ventas,ClienteRepository clientes,ProductoRepository productos,FacturaRepository facturas){this.ventas=ventas;this.clientes=clientes;this.productos=productos;this.facturas=facturas;}
 public List<Venta> listar(){return ventas.findAll();}
 @Transactional public Venta crear(VentaRequest r){if(r.items()==null||r.items().isEmpty())throw new ApiException("La venta debe tener productos");Cliente c=clientes.findById(r.clienteId()).orElseThrow(()->new ApiException("Cliente no encontrado"));Venta v=new Venta();v.setCliente(c);v.setFecha(LocalDateTime.now());BigDecimal total=BigDecimal.ZERO;for(ItemVenta item:r.items()){if(item.cantidad()==null||item.cantidad()<1)throw new ApiException("Cantidad inválida");Producto p=productos.findById(item.productoId()).orElseThrow(()->new ApiException("Producto no encontrado"));if(p.getStock()<item.cantidad())throw new ApiException("Stock insuficiente para: "+p.getNombre());p.setStock(p.getStock()-item.cantidad());productos.save(p);DetalleVenta d=new DetalleVenta();d.setVenta(v);d.setProducto(p);d.setCantidad(item.cantidad());d.setPrecioUnitario(p.getPrecio());v.getDetalles().add(d);total=total.add(p.getPrecio().multiply(BigDecimal.valueOf(item.cantidad)));}v.setTotal(total);Venta guardada=ventas.save(v);Factura f=new Factura();f.setVenta(guardada);f.setEmitida(LocalDateTime.now());f.setTotal(total);f.setNumero("FAC-"+System.currentTimeMillis());facturas.save(f);guardada.setFactura(f);return guardada;}
}
